        "link": "https://www.lemonde.fr/politique/live/2026/03/19/en-direct-municipales-2026-emmanuel-gregoire-appelle-a-battre-l-extreme-droite-a-paris-apres-le-soutien-de-facto-de-marine-le-pen-a-rachida-dati_6671274_823448.html",
        "orario": "14:10",
